const p=msg.payload||{};
if(p.type==='voice')return null;
const channel=msg.channel||'telegram';
const chatId=msg.chatId||p.chatId||p.chat?.id||p.message?.chat?.id;
let text=String(msg.userText||p.content||p.text||p.message?.text||'').trim();
if(!chatId)return null;
msg.chatId=chatId;msg.channel=channel;msg.userText=text;
const key='feiracircular_modo_'+channel+'_'+chatId;
let mode=flow.get(key)||'texto';
function direct(content){msg.payload={chatId,type:'message',content};msg.directText=content;return [null,msg];}
if(/^\/audio\b/i.test(text)||/^áudio$/i.test(text)){
  if(channel==='web')return direct('No Webchat, as respostas são em texto. No Telegram, use /audio.');
  flow.set(key,'audio');return direct('Preferência alterada: vou responder em áudio.');
}
if(/^\/texto\b/i.test(text)||/^texto$/i.test(text)){flow.set(key,'texto');return direct('Preferência alterada: vou responder em texto.');}
if(/^\/start\b/i.test(text)||/^ajuda$/i.test(text))return direct('Olá! Sou o FeiraBot, assistente do projeto FeiraCircular. Posso explicar ofertas, reservas, participação de feirantes, doações e localização de feiras. No Telegram use /texto ou /audio.');
if(!text)return direct('Envie uma pergunta sobre o FeiraCircular.');
msg.replyMode=channel==='web'?'texto':mode;
return [msg,null];

const data = msg.payload || {};

const answer =
    data.choices?.[0]?.message?.content;

let content = answer ||
    "Desculpe, não consegui formular uma resposta agora. Tente novamente.";

function escapeHTML(text) {
    return String(text)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;");
}

function formatTelegramHTML(text) {
    let formatted = escapeHTML(text);

    formatted = formatted.replace(
        /\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,
        '<a href="$2">$1</a>'
    );

    formatted = formatted.replace(
        /\*\*(.*?)\*\*/gs,
        "<b>$1</b>"
    );

    formatted = formatted.replace(
        /(^|[^*])\*([^*\n]+)\*/g,
        "$1<i>$2</i>"
    );

    return formatted.trim();
}

// Quando o usuário escolheu áudio,
// não envia resposta em texto.
if (msg.channel === "web" || msg.replyMode === "audio") {
    return null;
}

// Resposta normal em texto
msg.payload = {
    chatId: msg.chatId,
    type: "message",
    content: formatTelegramHTML(content),
    options: {
        parse_mode: "HTML"
    }
};

return msg;

const key = env.get("GROQ_API_KEY");

if (!key) {
    if (msg.channel === "web") { msg.statusCode = 503; msg.payload = {reply:"Configuração pendente: GROQ_API_KEY."}; return [null, null, msg]; }
    msg.payload = {
        chatId: msg.chatId,
        type: "message",
        content: "Configuração pendente: defina GROQ_API_KEY nas variáveis de ambiente do Node-RED."
    };
    return [null, msg];
}

msg.headers = {
    "Authorization": "Bearer " + key,
    "Content-Type": "application/json"
};

msg.payload = msg.llmRequest;

return [msg, null];

if (msg.payload.type !== "voice" || !msg.payload.path) {
    return null;
}

msg.filename = msg.payload.path;
msg.chatId = msg.payload.chatId;

return msg;

const audio = msg.payload;
const apiKey = env.get("GROQ_API_KEY");

if (!Buffer.isBuffer(audio)) {
    node.error("Áudio inválido.", msg);
    return null;
}

if (!apiKey) {
    node.error("GROQ_API_KEY não configurada.", msg);
    return null;
}

const boundary = "----NodeREDGroq" + Date.now();

const inicio = Buffer.from(
    "--" + boundary + "\r\n" +
    'Content-Disposition: form-data; name="model"\r\n\r\n' +
    "whisper-large-v3-turbo\r\n" +
    "--" + boundary + "\r\n" +
    'Content-Disposition: form-data; name="language"\r\n\r\n' +
    "pt\r\n" +
    "--" + boundary + "\r\n" +
    'Content-Disposition: form-data; name="file"; filename="audio.ogg"\r\n' +
    "Content-Type: audio/ogg\r\n\r\n"
);

const fim = Buffer.from(
    "\r\n--" + boundary + "--\r\n"
);

msg.payload = Buffer.concat([inicio, audio, fim]);

msg.headers = {
    "Authorization": "Bearer " + apiKey,
    "Content-Type": "multipart/form-data; boundary=" + boundary
};

return msg;

if (msg.statusCode !== 200 || !msg.payload?.text) {
    node.error("Não foi possível transcrever o áudio.", msg);
    return null;
}

const texto = msg.payload.text.trim();

msg.payload = {
    chatId: msg.chatId,
    type: "message",
    content: texto
};

return msg;

if (msg.replyMode !== "audio") {
    return null;
}

const apiKey = env.get("GEMINI_API_KEY");

if (!apiKey) {
    node.error("GEMINI_API_KEY não configurada.", msg);
    return null;
}

const data = msg.payload || {};
const resposta = data.choices?.[0]?.message?.content;

if (!resposta) {
    node.error("Nenhum texto recebido da LLM.", msg);
    return null;
}

msg.url =
    "https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash-preview-tts:generateContent";

msg.headers = {
    "x-goog-api-key": apiKey,
    "Content-Type": "application/json"
};

msg.payload = {
    contents: [
        {
            parts: [
                {
                    text: "Leia em português brasileiro, com voz natural e acolhedora: " + resposta
                }
            ]
        }
    ],
    generationConfig: {
        responseModalities: ["AUDIO"],
        speechConfig: {
            voiceConfig: {
                prebuiltVoiceConfig: {
                    voiceName: "Kore"
                }
            }
        }
    }
};

return msg;

if (msg.statusCode !== 200) {
    node.error("Erro na geração de áudio pelo Gemini.", msg);
    return null;
}

const parte =
    msg.payload?.candidates?.[0]?.content?.parts?.find(
        p => p.inlineData?.data
    );

if (!parte) {
    node.error("O Gemini não retornou dados de áudio.", msg);
    return null;
}

const audioBase64 = parte.inlineData.data;
const mimeType = parte.inlineData.mimeType || "";

if (!mimeType.includes("audio")) {
    node.error("Formato de áudio inesperado: " + mimeType, msg);
    return null;
}

msg.audioBuffer = Buffer.from(audioBase64, "base64");
msg.audioMimeType = mimeType;

return msg;

const audio = msg.audioBuffer;

if (!Buffer.isBuffer(audio)) {
    node.error("Áudio do Gemini não encontrado.", msg);
    return null;
}

const mime = msg.audioMimeType || "";
const taxa = Number(mime.match(/rate=(\d+)/)?.[1]) || 24000;

msg.filename = "C:\\NodeRED_Audios\\gemini_" +
    msg.chatId + "_" + Date.now() + ".pcm";

msg.payload = audio;
msg.sampleRate = taxa;

return msg;

const entrada = msg.filename;
const taxa = msg.sampleRate || 24000;

if (!entrada || !entrada.endsWith(".pcm")) {
    node.error("Arquivo PCM não encontrado.", msg);
    return null;
}

const saida = entrada.replace(/\.pcm$/, ".ogg");

msg.audioOgg = saida;

msg.payload =
    '-y -f s16le -ar ' + taxa +
    ' -ac 1 -i "' + entrada +
    '" -c:a libopus -b:a 32k "' + saida + '"';

return msg;

const resultado = msg.payload;
const caminho = msg.audioOgg;
const chatId = msg.chatId;

if (!resultado || resultado.code !== 0) {
    node.error(
        "Erro na conversão FFmpeg. Código: " +
        (resultado ? resultado.code : "desconhecido"),
        msg
    );
    return null;
}

if (!caminho || !chatId) {
    node.error("Caminho do áudio ou chatId ausente.", msg);
    return null;
}

msg.payload = {
    chatId: chatId,
    type: "voice",
    content: caminho
};

return msg;

// FEIRACIRCULAR - GS
// 5 intenções, 12 exemplos por intenção,
// 5 entidades com sinônimos e contexto por conversa.

// 1. CATÁLOGO DE INTENÇÕES
const catalog = {
    consultar_ofertas: [
        "quais ofertas estão disponíveis",
        "tem alimentos com desconto",
        "quero ver promoções",
        "mostrar ofertas",
        "o que está à venda",
        "tem frutas baratas",
        "como encontro produtos",
        "buscar alimentos disponíveis",
        "quais alimentos posso comprar",
        "ver produtos em oferta",
        "quero economizar na feira",
        "existem ofertas hoje"
    ],
    reservar_alimento: [
        "como reservar um alimento",
        "quero fazer uma reserva",
        "posso reservar uma oferta",
        "como funciona a reserva",
        "guardar produto para mim",
        "reservar frutas",
        "quero retirar minha reserva",
        "como retiro o alimento",
        "consigo cancelar a reserva",
        "reserva de alimentos",
        "posso separar uma cesta",
        "onde vejo minhas reservas"
    ],
    cadastrar_feirante: [
        "sou feirante e quero participar",
        "como cadastrar minha barraca",
        "quero anunciar alimentos",
        "como criar uma oferta",
        "cadastro de feirante",
        "sou vendedor de feira",
        "como vender excedentes",
        "quero publicar descontos",
        "como o feirante participa",
        "como recuperar parte da renda",
        "cadastrar meus produtos",
        "como divulgar alimentos"
    ],
    doar_alimentos: [
        "quero doar alimentos",
        "como funciona a doação",
        "posso doar excedentes",
        "sou uma organização social",
        "como receber doações",
        "destinar alimentos para doação",
        "como doar frutas",
        "qual o papel das ongs",
        "como ajudar instituições",
        "quero cadastrar uma organização",
        "doação de comida",
        "como encaminhar alimentos"
    ],
    localizar_feira: [
        "onde fica a feira",
        "quero encontrar uma feira",
        "localizar feiras próximas",
        "quais feiras participam",
        "tem feira no meu bairro",
        "onde retirar os alimentos",
        "buscar feira por região",
        "onde posso comprar",
        "como achar uma barraca",
        "feiras de são paulo",
        "qual endereço da feira",
        "encontrar feirante próximo"
    ]
};

// 2. ENTIDADES E SINÔNIMOS
const dictionaries = {
    categoria_alimento: {
        fruta: [
            "frutas", "banana", "bananas", "maçã", "maçãs",
            "laranja", "laranjas", "mamão", "mamões",
            "manga", "mangas", "uva", "uvas"
        ],
        verdura: [
            "verduras", "alface", "alfaces", "couve",
            "rúcula", "espinafre"
        ],
        legume: [
            "legumes", "cenoura", "cenouras", "batata",
            "batatas", "abobrinha", "abobrinhas"
        ],
        cesta: ["cestas", "kit", "kits", "combo", "combos"]
    },
    perfil_usuario: {
        feirante: ["vendedor", "barraqueiro", "comerciante"],
        consumidor: ["cliente", "comprador", "morador"],
        organizacao_social: [
            "ong", "ongs", "instituição", "instituições",
            "associação", "entidade social"
        ]
    },
    acao_plataforma: {
        comprar: ["compra", "adquirir", "pagar"],
        reservar: [
            "reserva", "reservas", "separar", "guardar",
            "reservando", "reservado"
        ],
        doar: ["doação", "doações", "destinar", "contribuir"],
        anunciar: ["anúncio", "publicar", "ofertar"]
    },
    condicao_alimento: {
        excedente: ["sobra", "sobras", "não vendido"],
        desconto: [
            "promoção", "promoções", "barato",
            "baratos", "preço reduzido"
        ],
        doacao: ["gratuito", "doado", "sem custo"]
    },
    localidade: {
        sao_paulo: ["sp", "sampa", "cidade de são paulo"],
        bairro: ["região", "vizinhança", "perto de casa"],
        feira: ["feira livre", "barraca", "ponto de retirada"]
    }
};

// 3. NORMALIZAÇÃO
function normalize(value) {
    return String(value || "")
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .toLowerCase()
        .replace(/[^a-z0-9 ]/g, " ")
        .replace(/\s+/g, " ")
        .trim();
}

const originalText = String(msg.userText || "");
const text = normalize(originalText);

function containsTerm(term) {
    const normalizedTerm = normalize(term);
    return normalizedTerm.length > 0 &&
        (" " + text + " ").includes(" " + normalizedTerm + " ");
}

// 4. IDENTIFICAÇÃO DAS ENTIDADES
msg.entities = {};

for (const [entity, values] of Object.entries(dictionaries)) {
    for (const [canonical, synonyms] of Object.entries(values)) {
        if ([canonical, ...synonyms].some(containsTerm)) {
            msg.entities[entity] = canonical;
            break;
        }
    }
}

// 5. IDENTIFICAÇÃO DAS INTENÇÕES
const scores = {};

for (const intent of Object.keys(catalog)) {
    scores[intent] = 0;
}

// Exemplos cadastrados continuam sendo utilizados.
for (const [intent, examples] of Object.entries(catalog)) {
    for (const example of examples) {
        const phrase = normalize(example);

        if (text === phrase) {
            scores[intent] += 100;
        } else if (text.includes(phrase)) {
            scores[intent] += 60;
        }
    }
}

// Regras para reconhecer variações de frases.
const rules = {
    consultar_ofertas: [
        /\b(ofertas?|promocoes?|descontos?)\b/,
        /\b(consultar|buscar|mostrar|ver)\b.*\b(produtos?|alimentos?)\b/,
        /\b(frutas?|legumes?|verduras?)\b.*\b(barat[oa]s?|disponiveis?)\b/
    ],
    reservar_alimento: [
        /\b(reservar|reserva|reservas|reservado|reservando)\b/,
        /\b(cancelar|cancelamento)\b.*\b(reserva|pedido)\b/,
        /\b(retirar|retirada|retiro)\b.*\b(alimento|produto|reserva|pedido)\b/,
        /\b(separar|guardar)\b.*\b(frutas?|alimentos?|produtos?|cesta)\b/
    ],
    cadastrar_feirante: [
        /\b(feirante|barraqueiro|vendedor)\b.*\b(cadastrar|participar|anunciar|vender)\b/,
        /\b(cadastrar|anunciar|publicar|vender)\b.*\b(barraca|produtos?|alimentos?|excedentes?)\b/,
        /\b(cadastro de feirante)\b/
    ],
    doar_alimentos: [
        /\b(doar|doacao|doacoes)\b/,
        /\b(ongs?|instituicoes?|organizacao social)\b/,
        /\b(destinar)\b.*\b(alimentos?|excedentes?)\b/
    ],
    localizar_feira: [
        /\b(localizar|encontrar|achar|buscar)\b.*\b(feiras?|barracas?)\b/,
        /\b(onde fica|qual endereco|feira proxima)\b/,
        /\b(feiras?)\b.*\b(bairro|regiao|perto|proxima)\b/
    ]
};

for (const [intent, patterns] of Object.entries(rules)) {
    for (const pattern of patterns) {
        if (pattern.test(text)) {
            scores[intent] += 50;
        }
    }
}

// Regras complementares com entidades.
if (msg.entities.acao_plataforma === "reservar") {
    scores.reservar_alimento += 30;
}
if (msg.entities.acao_plataforma === "doar") {
    scores.doar_alimentos += 30;
}
if (msg.entities.acao_plataforma === "anunciar") {
    scores.cadastrar_feirante += 30;
}
if (msg.entities.condicao_alimento === "desconto") {
    scores.consultar_ofertas += 20;
}

// Escolhe a intenção com maior pontuação.
const ranking = Object.entries(scores)
    .sort((a, b) => b[1] - a[1]);

const best = ranking[0];

msg.intent = best && best[1] > 0 ? best[0] : "fallback";
msg.intentScore = best && best[1] > 0 ? best[1] : 0;

// 6. CONTEXTO POR USUÁRIO E CANAL
const key = "feiracircular_contexto_" +
    (msg.channel || "telegram") + "_" +
    String(msg.chatId || "anonimo");

const previous = flow.get(key) || {};

msg.contextoAnterior = previous;

// Mantém a intenção anterior quando a pergunta
// é uma continuação sem intenção reconhecida.
const continuation = /^(e |mas |entao |depois |como faco |e se )/.test(text);

if (
    msg.intent === "fallback" &&
    continuation &&
    previous.intent &&
    previous.intent !== "fallback"
) {
    msg.intent = previous.intent;
    msg.intentScore = 10;
    msg.contextoHerdado = true;
} else {
    msg.contextoHerdado = false;
}

// Atualiza o contexto.
flow.set(key, {
    intent: msg.intent,
    entities: {
        ...(previous.entities || {}),
        ...msg.entities
    },
    ultimaPergunta: originalText
});

return msg;

const intentLabels={consultar_ofertas:'consultar ofertas',reservar_alimento:'reservar alimentos',cadastrar_feirante:'cadastrar feirantes',doar_alimentos:'doar alimentos',localizar_feira:'localizar feiras'};
const system=`Você é o FeiraBot, assistente do projeto acadêmico FeiraCircular, em São Paulo. Responda em português brasileiro, com clareza e objetividade. O projeto busca reduzir desperdício de alimentos em feiras livres, com modelo híbrido: feirantes podem anunciar excedentes com desconto para recuperar parte da renda, consumidores podem encontrar ofertas e reservar alimentos, e organizações sociais podem receber alimentos destinados a doação. A plataforma é um protótipo acadêmico; não afirme que ofertas, cadastros, reservas, estoques, horários, pagamentos, endereços ou retiradas reais já estão disponíveis. Não invente valores, locais, datas ou funcionalidades implementadas. Explique o funcionamento proposto e diga que dados reais dependem da implantação. As cinco áreas de atendimento são: ofertas, reservas, cadastro de feirantes, doações e localização de feiras. Quando não houver dados, diga isso explicitamente. Não peça CPF, endereço ou outros dados sensíveis. Intenção detectada (classificação aproximada por exemplos): ${intentLabels[msg.intent]||'não identificada'}. Entidades detectadas: ${JSON.stringify(msg.entities)}. Última intenção na conversa: ${msg.contextoAnterior?.intent||'nenhuma'}. Se a pergunta for ambígua, peça esclarecimento.`;
msg.llmRequest={model:'openai/gpt-oss-20b',messages:[{role:'system',content:system},{role:'user',content:msg.userText}],temperature:0.2};
return msg;

if(msg.channel!=='web')return null;
const reply=msg.payload?.choices?.[0]?.message?.content||'Não consegui responder agora.';
msg.payload={reply,intent:msg.intent,entities:msg.entities};return msg;
